import {plannerCalendar} from './planner-calendar.mjs';
const dayLabel=d=>new Date(d+'T12:00Z').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'});
const shift=(d,n)=>new Date(Date.parse(d+'T12:00Z')+n*86400000).toISOString().slice(0,10);
export function plannerDays(d,{e,taskLink,eventLink,showCompleted=false}){
 const task=t=>'<article class="planner-task"><small>Due · '+e(t.subject)+'</small><strong>'+taskLink(t)+'</strong><small>'+e(t.className||'')+'</small><span>'+e(t.status?({assigned:'To do',draft:'In progress',overdue:'Overdue',submitted:'Turned in',returned:'Returned',feedback:'New feedback'}[t.status]||t.status):'Class deadline')+(t.minutes?' · '+t.minutes+' min':'')+'</span></article>';
 const event=r=>'<details class="planner-event '+(r.status==='draft'?'planner-draft':r.status==='cancelled'?'planner-cancelled':'')+'"><summary><small>'+e(r.time||'All day')+' · '+e(r.kind)+(r.status!=='published'?' · '+e(r.status):'')+'</small><strong>'+e(r.title)+'</strong><span>'+e(r.subject)+'</span></summary><p class="vle-prose">'+e(r.description||'')+'</p><small>'+e(r.className)+(r.duration?' · '+r.duration+' min':'')+'</small>'+eventLink(r)+'</details>';
 const section=day=>{const tasks=day.deadlines.filter(t=>showCompleted||!['submitted','returned','feedback'].includes(t.status)),items=[...day.events.map(event),...tasks.map(task)],finished=day.deadlines.length-tasks.length;return '<section class="planner-day"><header><h3>'+dayLabel(day.date)+'</h3><small>'+day.deadlines.length+' deadline'+(day.deadlines.length===1?'':'s')+(day.minutes?' · '+day.minutes+' min':'')+'</small></header>'+items.slice(0,3).join('')+(items.length>3?'<details class="planner-more"><summary>Show '+(items.length-3)+' more</summary>'+items.slice(3).join('')+'</details>':'')+(!items.length?'<p class="planner-empty">Nothing due</p>':'')+(finished?'<small class="planner-finished">'+finished+' completed / turned in</small>':'')+'<details class="planner-lessons"><summary>'+day.lessons.length+' scheduled lessons</summary>'+day.lessons.map(l=>'<p><b>'+e(l.from?l.from+'–'+l.to:l.period)+'</b><span>'+e(l.className)+(l.room?' · '+e(l.room):'')+'</span></p>').join('')+'</details></section>';};
 return '<div class="planner-week">'+d.days.slice(0,5).map(section).join('')+'</div>'+ (d.days.slice(5).some(x=>x.deadlines.length||x.events.length)?'<details class="vle-panel"><summary>Weekend work & events</summary><div class="planner-week planner-weekend">'+d.days.slice(5).map(section).join('')+'</div></details>':'');
}
export function createPlannerUI({e,api,ui,link}){let current=null,exportURL='';
 const staff=()=>ui.actor().role!=='student',hidden=(n,v)=>'<input type="hidden" name="'+n+'" value="'+e(v??'')+'">';
 const option=(v,t,selected)=>'<option value="'+e(v)+'" '+(v===selected?'selected':'')+'>'+e(t)+'</option>';
 function editor(d,r={}){return '<form data-vle="calendar-save">'+hidden('id',r.id)+hidden('expectedRevision',r.revision||0)+'<div class="vle-form-grid"><label class="vle-field">Class<select name="classId" required '+(r.id?'disabled':'')+'>'+d.classes.map(c=>option(c.id,c.name,r.classId||d.selectedClass||d.classes[0]?.id)).join('')+'</select></label>'+(r.id?hidden('classId',r.classId):'')+'<label class="vle-field">Event title<input name="title" value="'+e(r.title||'')+'" maxlength="160" required></label><label class="vle-field">Date<input type="date" name="date" value="'+e(r.date||d.start)+'" required></label><label class="vle-field">Type<select name="kind">'+['Lesson focus','Assessment','Reminder','Class event'].map(v=>option(v,v,r.kind||'Lesson focus')).join('')+'</select></label></div><label class="vle-field">Instructions / preparation<textarea name="description" maxlength="5000">'+e(r.description||'')+'</textarea></label><details><summary>Set a time (optional)</summary><div class="vle-form-grid"><label class="vle-field">Start time · Tashkent<input type="time" name="time" value="'+e(r.time||'')+'"></label><label class="vle-field">Duration (minutes)<input type="number" name="duration" min="5" max="480" value="'+(r.duration||45)+'"></label></div></details><p><button class="text-button" type="button" data-planner-workload>Check class deadlines for this day</button></p><p role="status" data-planner-workload-result></p><small>Calendar events are reminders and lesson plans. Create an assignment in Classwork when students need to hand in graded work.</small><div class="vle-actions"><button type="submit" name="intent" value="draft" class="btn">Save private draft</button><button type="submit" name="intent" value="publish" class="btn primary">'+(r.id?'Save & publish':'Publish to class')+'</button></div></form>';}
 async function page(params){const q=new URLSearchParams();for(const k of ['date','classId','cancelled'])if(params.get(k))q.set(k,params.get(k));const d=await api('planner?'+q);current=d;d.selectedClass=params.get('classId')||'';const selected=params.get('event'),event=d.days.flatMap(x=>x.events).find(x=>x.id===selected);if(selected&&!event)throw Error('This event is unavailable in this week. Open the week containing it.');const showCompleted=params.get('completed')==='1',filters={view:'week',date:d.start,...(d.selectedClass?{classId:d.selectedClass}:{}),...(showCompleted?{completed:'1'}:{}),...(params.get('cancelled')?{cancelled:params.get('cancelled')}:{})};
  return '<div class="learning-section-title"><h2>Weekly learning plan</h2><div class="vle-actions">'+link('← Previous week',{...filters,date:shift(d.start,-7)})+link('Next week →',{...filters,date:shift(d.start,7)})+'<button type="button" class="btn" id="planner-export">Download calendar</button></div></div><form id="planner-filters" class="community-filters"><label>Week of <input type="date" name="date" value="'+d.start+'"></label><label>Class <select name="classId">'+option('','All my classes',d.selectedClass)+d.classes.map(c=>option(c.id,c.name,d.selectedClass)).join('')+'</select></label><label class="community-check"><input type="checkbox" name="completed" '+(showCompleted?'checked':'')+'> Show completed work</label>'+(staff()?'<label class="community-check"><input type="checkbox" name="cancelled" '+(params.get('cancelled')==='1'?'checked':'')+'> Show cancelled events</label>':'')+'</form><p class="muted">'+d.summary.deadlines+' deadlines · '+d.summary.events+' published events'+(d.student?' · '+d.summary.minutes+' estimated minutes remaining'+(d.summary.unestimated?' · '+d.summary.unestimated+' tasks have no time estimate':''):' · Task estimates are per assignment, not a daily teaching load')+'. School time: Tashkent.</p>'+(staff()?(event?'<section class="vle-panel"><div class="learning-section-title"><h3>Edit class event</h3>'+link('Close editor',filters)+'</div>'+editor(d,event)+'<button type="button" class="text-button" data-calendar-toggle="'+e(event.id)+'" data-revision="'+event.revision+'" data-cancelled="'+(event.status!=='cancelled')+'">'+(event.status==='cancelled'?'Restore event':'Cancel event')+'</button></section>':'<details class="vle-panel"><summary>＋ Add a lesson focus or class event</summary>'+editor(d)+'</details>'):'')+plannerDays(d,{e,showCompleted,taskLink:t=>link(t.title,{class:t.classId,assignment:t.id}),eventLink:r=>staff()?'<p>'+link('Edit / cancel event',{...filters,event:r.id})+'</p>':''})+(d.undated.length?'<details class="vle-panel"><summary>'+d.undated.length+' tasks without a deadline</summary>'+d.undated.map(t=>'<p>'+link(t.title,{class:t.classId,assignment:t.id})+' · '+e(t.className)+'</p>').join('')+'</details>':'')+'<p class="muted">Calendar download includes this week’s visible assignment deadlines and published events. It is a file download; no external calendar connection is used.</p>';
 }
 function bind(root){const controls=new Map([...root.querySelectorAll('#planner-filters input,#planner-filters select')].map(x=>[x.name,x.type==='checkbox'?x.checked:x.value]));root.querySelector('#planner-filters')?.addEventListener('change',ev=>{if(ui.isDirty?.()&&!confirm('Discard unsaved event changes?')){if(ev.target.type==='checkbox')ev.target.checked=controls.get(ev.target.name);else ev.target.value=controls.get(ev.target.name);return;}const d=Object.fromEntries(new FormData(ev.currentTarget));for(const k of ['completed','cancelled'])if(d[k])d[k]='1';ui.dirty(false);location.hash='/classroom?'+new URLSearchParams({view:'week',...d});});root.querySelector('#planner-export')?.addEventListener('click',()=>{if(exportURL)URL.revokeObjectURL(exportURL);exportURL=URL.createObjectURL(new Blob([plannerCalendar(current,{includeCompleted:new URLSearchParams(location.hash.split('?')[1]).get('completed')==='1'})],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=exportURL;a.download='WIST-week-'+current.start+'.ics';a.click();});root.querySelector('[data-calendar-toggle]')?.addEventListener('click',async ev=>{const b=ev.currentTarget;b.disabled=true;try{await api('calendar-cancel',{id:b.dataset.calendarToggle,expectedRevision:Number(b.dataset.revision),cancelled:b.dataset.cancelled==='true'});const p=new URLSearchParams(location.hash.split('?')[1]);p.delete('event');ui.dirty(false);location.hash='/classroom?'+p;}catch(error){ui.toast(error.message);b.disabled=false;}});root.querySelector('[data-planner-workload]')?.addEventListener('click',async ev=>{const f=ev.currentTarget.closest('form'),box=f.querySelector('[data-planner-workload-result]');try{const values=new FormData(f),date=values.get('date'),d=await api('planner?'+new URLSearchParams({date,classId:values.get('classId')})),day=d.days.find(x=>x.date===date);if(box.isConnected)box.textContent=day.deadlines.length+' assignment deadline(s), '+day.deadlines.reduce((n,t)=>n+t.minutes,0)+' estimated task minutes, '+day.events.filter(x=>x.status==='published').length+' published event(s).'+(day.deadlines.some(t=>!t.minutes)?' Some tasks have no time estimate.':'');}catch(error){if(box.isConnected)box.textContent=error.message;}});}
 function readAction(action,d,intent){if(action==='calendar-save'){d.status=intent==='draft'?'draft':'published';d.duration=Number(d.duration||45);}}
 return{page,bind,readAction};
}
